using UnityEngine;
namespace Fsp.World{public sealed class SaltworksRoadLink:MonoBehaviour{void Start(){if(transform.childCount>0)return;Road(new Vector3(-60,.05f,35),new Vector3(-15,.05f,165),6.5f);Road(new Vector3(105,.05f,92),new Vector3(-15,.05f,165),6.5f);}void Road(Vector3 a,Vector3 b,float w){var s=Shader.Find("Standard");var m=new Material(s!=null?s:Shader.Find("Sprites/Default"));m.color=new Color(.25f,.24f,.22f);var prev=a;for(int i=1;i<=11;i++){float t=i/11f;var p=Vector3.Lerp(a,b,t);p.x+=Mathf.Sin(t*Mathf.PI)*7;var d=p-prev;var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="SaltworksRoad";g.transform.SetParent(transform,false);g.transform.position=(p+prev)*.5f;g.transform.rotation=Quaternion.LookRotation(d.normalized);g.transform.localScale=new Vector3(w,.12f,d.magnitude+.7f);var r=g.GetComponent<Renderer>();if(r!=null)r.sharedMaterial=m;prev=p;}}}}
